use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply, ToolRequest};
use crate::aap::caps::types::{AgentResponse, Intent, LlmError};

struct Node;

/// The only tool in this node's scope.
const TOOL_NAME: &str = "lookup";

/// Upper bound on tool-orchestration rounds before the node gives up.
const MAX_ROUNDS: usize = 4;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing question",
        Intent::TechnicalSupport => "technical support",
        Intent::AccountChange => "account change",
        Intent::GeneralInquiry => "general inquiry",
        Intent::Unknown => "unknown",
    }
}

fn render_prompt(question: &str, knowledge: &[String]) -> String {
    let mut s = String::from("Customer question:\n");
    s.push_str(question);
    s.push_str("\n\nKnowledge:\n");
    for k in knowledge {
        s.push_str("- ");
        s.push_str(k);
        s.push('\n');
    }
    s
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let ConversationContext {
            intent,
            question,
            knowledge,
        } = ctx;

        // Ground the model in the knowledge base before the first round.
        let mut context = knowledge;
        context.extend(kb_read::lookup(&question));

        let system = format!(
            "You are a customer-support agent. The request's intent is: {}. \
             Answer the customer's question using the supplied knowledge. \
             You may request one tool, `{}`, by asking for a lookup query. \
             Reply in plain text when you have an answer.",
            intent_label(intent),
            TOOL_NAME,
        );

        let mut transcript = render_prompt(&question, &context);

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(&system, &transcript) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(ToolRequest { tool, query }) => {
                    if tool != TOOL_NAME {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool `{}` is not in scope", tool),
                        });
                    }
                    let results = kb_read::lookup(&query);
                    transcript.push_str(&format!("\n\nResult of lookup({:?}):\n", query));
                    for r in &results {
                        transcript.push_str("- ");
                        transcript.push_str(r);
                        transcript.push('\n');
                    }
                    if results.is_empty() {
                        transcript.push_str("(no matches)\n");
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: format!("no answer after {} tool rounds", MAX_ROUNDS),
        })
    }
}

export!(Node);
